        throw new IllegalArgumentException("unexpected quote line: " + line);
    }
    return new FxQuote(t[0], LocalDate.parse(t[1]), new BigDecimal(t[2]));
}

/**
 * True when the vendor answered with the previous business day's value instead of the requested date
 * (a trailing {@code ~N} on the line, e.g. a holiday in the vendor calendar).
 */
public static boolean carriedForward(String line) {
    String[] t = line.trim().split("\\s+");
    return t.length > 3 && t[3].startsWith("~");
}

