/** FX rates for settlement and display, backed by the vendor CLI with a per-run cache. */
public class RateService {
    /** Vendor source 2 is the settlement reference; sources 1 and 3 are buy/sell quotes. */
    private static final int SETTLEMENT_SOURCE = 2;

    private final FxqClient client;
    private final Map<String, String> cache = new HashMap<>();
    private int vendorCalls;

    public RateService(FxqClient client) {
        this.client = client;
    }

    /** Quote shown on the app rate board (default source, unchanged). */
    public FxQuote quote(String currency, LocalDate date) {
        return FxqClient.parse(fetch(CurrencyPairs.pairOf(currency), date, null));
    }

    /** Rate applied to card transactions of the given KST settlement date. */
    public BigDecimal settlementRate(String currency, LocalDate date) {
        String pair = CurrencyPairs.pairOf(currency);
        String line = fetch(pair, date, null);
        if (FxqClient.carriedForward(line)) {
            // Vendor holiday: the default source repeats the previous business day, which is not this date's rate.
            line = fetch(pair, date, SETTLEMENT_SOURCE);
            if (FxqClient.carriedForward(line)) {
                throw new IllegalStateException("no settlement rate for " + pair + " " + date + ": " + line);
            }
        }
        return FxqClient.parse(line).rate();
    }

    private String fetch(String pair, LocalDate date, Integer source) {
        return cache.computeIfAbsent(pair + "@" + date + "#" + source, k -> {
            vendorCalls++;
            return client.rate(pair, date, source);
        });
    }

